public static boolean isRetailEnabledAndInUse()
{
    boolean ret = next isRetailEnabledAndInUse();

    ret = ret || FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance());

    return ret;
}

public static boolean isRetailInUse()
{
    boolean ret = next isRetailInUse();

    ret = ret || FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance());

    return ret;
}
